#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ProgressRing's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/progress_ring.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The progress, from 0 to maximum; a value outside that range is drawn clamped to it. Not finite throws std::invalid_argument.
template <typename Declaring>
struct ProgressRingValueCapability {
    PropertyCell<double, ProgressRingValueCapability<Declaring>> value{0.0};

    static void assign(ProgressRingValueCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.value), incoming);
        if (!capability.value.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.value));
    }
};

// The value of a full ring (100 by default). Not finite or not above zero throws std::invalid_argument.
template <typename Declaring>
struct ProgressRingMaximumCapability {
    PropertyCell<double, ProgressRingMaximumCapability<Declaring>> maximum{100.0};

    static void assign(ProgressRingMaximumCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.maximum), incoming);
        if (!capability.maximum.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.maximum));
    }
};

// Whether the ring shows activity without an amount: a turning arc instead of the value.
template <typename Declaring>
struct ProgressRingIndeterminateCapability {
    PropertyCell<bool, ProgressRingIndeterminateCapability<Declaring>> indeterminate{false};

    static void assign(ProgressRingIndeterminateCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.indeterminate), incoming);
        if (!capability.indeterminate.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.indeterminate));
    }
};

// Every ProgressRing capability, in the order the declaring class takes them.
template <typename Declaring>
struct ProgressRingCapabilities : public ProgressRingValueCapability<Declaring>,
                                  public ProgressRingMaximumCapability<Declaring>,
                                  public ProgressRingIndeterminateCapability<Declaring> {};

} // namespace gui_forms
